# Expected digests generated by test/joblib/gen_expected.py (joblib 1.6.0).

import numpy as np
import joblib
from joblib import Parallel, delayed, Memory

EXP = {
    "f3d": "216113a3e30f93491ce9db20e93ec471",
    "f2d": "1dece7d06c0ccd26c2da2ebe4137c4c4",
    "fT": "0b61cda4f2fb2ff91210d21de3f9ce61",
    "fslice": "1e64eb2045e570efa956c955b94b8bd9",
    "i1d": "778aff2f14a22e4446193e8b260ff86c",
    "big": "515f3c24ae4755ce5f557f1aabed8ce5",
    "sq": "5357e9df522e9de8aabc4a7e60da5b9e",
    "b": "9cc4bc25428670f477919864cc1c1808",
    "f32": "f8efa3d895868602091070e5ecfc3966",
    "i32": "a049fe74cc7d0167abea8fa0e590238c",
    "scalar": "5c72ee98c2b92f777b9dcabb66eeddd5",
    "d4": "48d55bbdf8def35ec7317b264db74ea9",
}

@test
def t_hash():
    a = np.arange(24, dtype=float).reshape(2, 3, 4) / 7.0
    assert joblib.hash(a) == EXP["f3d"]
    assert joblib.hash(a[0]) == EXP["f2d"]
    assert joblib.hash(a[0].T) == EXP["fT"]
    assert joblib.hash(a[:, 1, ::2]) == EXP["fslice"]
    assert joblib.hash(np.arange(10)) == EXP["i1d"]
    assert joblib.hash(np.ones((70000, 2))) == EXP["big"]
    assert joblib.hash(np.zeros((300, 300))) == EXP["sq"]
    assert joblib.hash(np.array([True, False, True])) == EXP["b"]
    assert joblib.hash(np.arange(5, dtype=np.float32)) == EXP["f32"]
    assert joblib.hash(np.arange(5, dtype=np.int32)) == EXP["i32"]
    assert joblib.hash(np.array(3.5)) == EXP["scalar"]
    assert joblib.hash(np.zeros((2, 2, 2, 2))) == EXP["d4"]

def sq(x: int, k: int):
    return x * x + k

@test
def t_parallel():
    r = Parallel(n_jobs=2, backend="threading")(delayed(sq)(i, 1) for i in range(6))
    assert r == [1, 2, 5, 10, 17, 26]
    with joblib.parallel_config(backend="threading", n_jobs=2):
        r2 = Parallel()(delayed(sq)(i, k=0) for i in range(3))
    assert r2 == [0, 1, 4]

@test
def t_memory():
    calls = {"n": 0}
    def heavy(a):
        calls["n"] += 1
        return a.T @ a
    mem = Memory(location="/tmp/jlcache_unused", verbose=0)
    c = mem.cache(heavy)
    F = np.arange(12.0).reshape(4, 3)
    r1 = c(F); r2 = c(F); r3 = c(F[:2])
    assert calls["n"] == 2
    assert np.array_equal(r1, r2)
    assert r3.shape == (3, 3)
    assert np.array_equal(r1, F.T @ F)

t_hash()
t_parallel()
t_memory()

import openmp
def slow_id(i: int):
    # uneven work so threads finish out of order
    s = 0.0
    for k in range((7 - i % 7) * 20000):
        s += float(k % 3)
    # team size of the enclosing parallel region (1 when run serially)
    return (i, openmp.get_num_threads(), s > -1.0)

@test
def t_threads():
    r = Parallel(n_jobs=4, backend="threading")(delayed(slow_id)(i) for i in range(40))
    assert [t[0] for t in r] == list(range(40))
    assert all(t[1] == 4 for t in r[1:])  # ran inside a 4-thread team
    r1 = Parallel(n_jobs=1)(delayed(slow_id)(i) for i in range(5))
    assert all(t[1] == 1 for t in r1)
    with joblib.parallel_config(backend="threading", n_jobs=3):
        r3 = Parallel()(delayed(slow_id)(i) for i in range(12))
    assert [t[0] for t in r3] == list(range(12))
    assert all(t[1] == 3 for t in r3[1:])
    rs = Parallel(n_jobs=4, backend="sequential")(delayed(slow_id)(i) for i in range(6))
    assert all(t[1] == 1 for t in rs)
    assert Parallel(n_jobs=2)(delayed(sq)(i, 0) for i in range(0)) == []

t_threads()
